#include "power_policy.hpp"
#include "semver.hpp"
#include "game_engine.hpp"
#include <cassert>
#include <iostream>
using namespace remora;
static void solve(GameEngine&e){for(int tries=0;tries<100000;tries++){auto&s=e.s;if(s.phase==Phase::Clear||s.phase==Phase::ReactionResult)return;assert(s.phase!=Phase::Over);switch(s.phase){case Phase::Input:{int n=s.sequence[s.mode==1?s.sequence.size()-1-s.input:s.input];if(s.mirror)n=7-n;e.press(n);break;}case Phase::ReactionGo:{e.advance(150);int n=s.target;if(s.difficulty==3)n=7-n;if(s.difficulty==4)n+=(n-1)%3==2?-1:1;e.press(n);break;}case Phase::MazeInput:{auto i=std::find(s.path.begin(),s.path.end(),s.current);assert(i+1<s.path.end());int d=*(i+1)-s.current;e.press(d==-s.cols?2:d==s.cols?5:d==1?3:1);break;}case Phase::Whack:{int round=s.round;for(size_t i=0;i<s.cues.size()&&s.round==round&&s.phase==Phase::Whack;i++){auto c=s.cues[i];if(c.done||c.type==1)continue;if(c.type==3)e.keyDown(c.target);else{e.press(c.target);if(c.type==2){e.advance(20);e.press(c.target);}}}e.advance(10);break;}case Phase::Potato:if(s.green)e.press(s.target);else e.advance(10);break;case Phase::DirectionInput:e.press(s.mapping[s.chain[s.chainIndex]]);break;case Phase::MissingInput:e.press(s.answers[s.index]);break;case Phase::DecoderInput:{int n=s.answers[s.index];for(int digit=2;digit>=0;digit--){int value=digit==2?n%10:digit==1?n/10%10:n/100;while(s.digits[s.digitIndex]!=value)e.press(6);if(digit)e.press(1);}e.press(5);break;}case Phase::Snake:s.food=s.body[0]+1;e.press(3);e.advance(s.tickMs);break;case Phase::Pong:s.bx=24;s.by=34;s.vx=0;s.vy=-3;e.advance(40);break;default:e.advance(10);break;}}assert(false);}
int main(){auto v=SemVer::parse("1.10.0"),old=SemVer::parse("1.9.9");assert(v.valid&&v.compare(old)>0);assert(!SemVer::parse("01.2.3").valid);assert(SemVer::parse("1.0.0-alpha.2").compare(SemVer::parse("1.0.0-alpha.10"))<0);assert(SemVer::parse("1.0.0+build").compare(SemVer::parse("1.0.0"))==0);PowerPolicy p;PowerInput i{false,50,0,false};assert(p.begin(0,i)==PowerPhase::Standby);i.keys=5;p.update(10,i);assert(p.update(2010,i)==PowerPhase::Play);i.usb=true;i.percent=80;assert(p.update(2020,i)==PowerPhase::ChargeNotice);assert(p.update(4020,i)==PowerPhase::Standby);for(int g=0;g<GameCount;g++)for(int d=0;d<5;d++){GameEngine e;e.start(g,d);solve(e);assert(e.s.score>0);}std::cout<<"Native core: all 11 games x 5 presets, power policy and SemVer OK\n";}
